import assert from 'node:assert/strict';
import test from 'node:test';
import { checkPreparedTransfer } from '../src/services/dat';

// Generated by apps/api/lib/tx.mjs for a 5.00 devnet-USDC transfer.
const fixture = {
  owner: 'GyfFHe77pcZtdgGnWGw4T1VxCPB6JJyGLfjzMagDdsz3',
  recipient: '8u8LCMQvMKrFxHbn326Ltcqv72HDPEC5FPMgPC3mXvxV',
  otherWallet: 'Hy6psfgdEAs9KVVxgG1i9WXhpzQ1BjGus4AZXzdJwwSE',
  message: '',
};

test('the phone accepts the exact transfer prepared by the server', () => {
  checkPreparedTransfer(fixture.message, { wallet: fixture.owner, recipient: fixture.recipient, units: 5_000_000n });
});

test('the phone refuses changed payment facts before signing', () => {
  const refused = /different transfer.*Nothing was signed/;
  assert.throws(() => checkPreparedTransfer(fixture.message, { wallet: fixture.otherWallet, recipient: fixture.recipient, units: 5_000_000n }), refused);
  assert.throws(() => checkPreparedTransfer(fixture.message, { wallet: fixture.owner, recipient: fixture.otherWallet, units: 5_000_000n }), refused);
  assert.throws(() => checkPreparedTransfer(fixture.message, { wallet: fixture.owner, recipient: fixture.recipient, units: 4_000_000n }), refused);
  assert.throws(() => checkPreparedTransfer('not base64', { wallet: fixture.owner, recipient: fixture.recipient, units: 5_000_000n }), refused);
});
